def find_nth_good_integer(N: int) -> int:
    def is_good_integer(num: int) -> bool:
        while num > 0:
            digit = num % 10
            if digit % 2 != 0:
                return False
            num //= 10
        return True

    count = 0
    current = 0
    while True:
        if is_good_integer(current):
            count += 1
            if count == N:
                return current
        current += 1
